export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-voz-0001", "section": "service", "who": "rubric", "text": "Всемирное воздвижение священного и животворящего креста господня"},
  {"id": "ru-voz-0002", "section": "service", "who": "reader", "text": "НА МАЛОЙ ВЕЧЕРНЕ На «Господи воззвах:» стихиры на 4, глас 1 Подобен: «Небесных полков:»*"},
  {"id": "ru-voz-0003", "section": "service", "who": "reader", "text": "Крест возносится – и демоны прогоняются, / разбойник же врата Эдема открывает; / смерть умерщвлена и ныне ничтожной явилась, / Христос же возвеличен. / Потому веселитесь, все на земле рожденные: / проклятие отменено! (2)"},
  {"id": "ru-voz-0004", "section": "service", "who": "reader", "text": "Придите, все боголюбивые, / Крест священный видя возносимым, / возвеличим вместе и славу воздадим / единому Искупителю и Богу, взывая: / «Распятый на древе Креста, / не презри нас, Тебе молящихся!»"},
  {"id": "ru-voz-0005", "section": "service", "who": "reader", "text": "Горечь в сладость претворяя, / Моисей избавил в древности Израиль, / этим образом предначертывая Крест. / Мы же, все верные, с божественным благоговением / таинственно его изображая в сердцах наших всегда, / спасаемся силою его."},
  {"id": "ru-voz-0006", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 6, самогласен"},
  {"id": "ru-voz-0007", "section": "service", "who": "reader", "text": "В сей день насаждение животворное / из недоступных недр земли исходит, / воскресение пригвожденного на нем Христа являет, / и, воздвигаемый руками священников / возвещает вознесение Его на небеса. / Благодаря ему наш состав после падения на землю / имеет гражданство на небесах. / Потому благодарственно воззовем: / «Господи, вознесенный на нем / и чрез него и нас вознесший, / небесной Твоей радости нас удостой / как Человеколюбец!»"},
  {"id": "ru-voz-0008", "section": "service", "who": "reader", "text": "Свет отрадный:"},
  {"id": "ru-voz-0009", "section": "service", "who": "rubric", "text": "и прокимен дня."},
  {"id": "ru-voz-0010", "section": "service", "who": "reader", "text": "Стихиры на стиховне, глас 2, Подобен: «Дом Евфрафов:»*"},
  {"id": "ru-voz-0011", "section": "service", "who": "reader", "text": "Водою обоготворяющей / и кровию Твоею, Слово, / радостно Церковь украшается, / как невеста, / славу Креста воспевая. Стих:"},
  {"id": "ru-voz-0012", "section": "service", "who": "reader", "text": "Возносите Господа, Бога нашего, и поклоняйтесь подножию ног Его, / ибо свято оно. Пс 98:5"},
  {"id": "ru-voz-0013", "section": "service", "who": "reader", "text": "Копье с Крестом вознося, / гвозди и все иное, / чем живоносное Христово тело / было пригвождено, / Ему поклонимся! Стих:"},
  {"id": "ru-voz-0014", "section": "service", "who": "reader", "text": "Бог же, Царь наш прежде века, / соделал спасение посреди земли. Пс 73:12"},
  {"id": "ru-voz-0015", "section": "service", "who": "reader", "text": "Когда Амалика Моисей побеждал, / руки ввысь простирая крестообразно, / он прообразовал / Христово страдание пречистое."},
  {"id": "ru-voz-0016", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 6 В сей день древо явилось, / в сей день род евреев погиб, / в сей день верные цари веру проявляют. / И Адам из-за дерева отпал, / и от Древа же демоны затрепетали. / Всесильный Господи, слава Тебе!"},
  {"id": "ru-voz-0017", "section": "service", "who": "reader", "text": "Тропарь, глас 1 Спаси, Господи, людей Твоих / и благослови наследие Твоё, / победы над неприятелями даруя / и Крестом Твоим сохраняя Твой народ."},
  {"id": "ru-voz-0018", "section": "service", "who": "rubric", "text": "Также ектения и отпуст."},
  {"id": "ru-voz-0019", "section": "service", "who": "rubric", "text": "Всемирное воздвижение священного и животворящего креста господня"},
  {"id": "ru-voz-0020", "section": "service", "who": "reader", "text": "НА ВЕЛИКОЙ ВЕЧЕРНЕ На"},
  {"id": "ru-voz-0021", "section": "service", "who": "reader", "text": "«Господи воззвах»"},
  {"id": "ru-voz-0022", "section": "service", "who": "rubric", "text": "стихиры на 8, глас 6."},
  {"id": "ru-voz-0023", "section": "service", "who": "reader", "text": "Подобен: Все отложив:"},
  {"id": "ru-voz-0024", "section": "service", "who": "reader", "text": "Крест возвышаемый / все творение побуждает / воспевать пречистое страдание Вознесенного на нем. / Ибо Умертвивший на нем нашего убийцу / умерщвленных оживил, / и сделал их прекрасными, / и удостоил иметь гражданство на небесах, как милосердный, / по преизбытку благости. / Потому, радуясь, вознесем имя Его / и возвеличим Его крайнее снисхождение. (3)"},
  {"id": "ru-voz-0025", "section": "service", "who": "reader", "text": "Моисей прообразовал тебя, / простерши руки ввысь, / и в бегство обращая Амалика мучителя, / Крест драгоценный, верных похвала, / страдальцев твердость, / Апостолов украшение, / защитник праведных, / всех преподобных спасение. / Потому все творение, / видя тебя возвышаемым, веселится / и торжествует, славя Христа, / через тебя сблизившего разделенное / по крайней благости. (3)"},
  {"id": "ru-voz-0026", "section": "service", "who": "reader", "text": "Крест всеблагоговейно чтимый, / который радостно окружают полки Ангелов, / ты, в сей день воздвигаемый, / божественным мановением возносишь всех, / отверженных за похищение пищи / и ниспавших в смерть. / Потому мы, с верою лобзая тебя сердцем и устами, / освящение почерпаем, возглашая: / «Возносите Христа, преблагого Бога, / и поклонитесь Его божественному подножию!» (2)"},
  {"id": "ru-voz-0027", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 2: Придите, все народы, / благословенному Древу поклонимся, / чрез которое настала вечная правда. / Ибо праотца Адама древом обольстивший / Крестом уловляется; / и, низвергшись, падает падением неудержимым / насильно завладевший царским созданием. / Кровию Божией яд змия смывается, / и уничтожено проклятие праведного осуждения, / когда Праведник осужден был судом неправедным. / Ибо Древом надлежало древо исцелить / и страданием Бесстрастного на Древе / уничтожить страсти осужденного. / Но слава, Христе Царь, / Твоему повергающему в трепет промыслу о нас, / которым Ты спас всех, / как благой и Человеколюбец."},
  {"id": "ru-voz-0028", "section": "service", "who": "rubric", "text": "Вход. Прокимен дня. И чтения праздника:"},
  {"id": "ru-voz-0029", "section": "service", "who": "reader", "text": "1. Исхода чтение"},
  {"id": "ru-voz-0030", "section": "service", "who": "reader", "text": "Поднял Моисей сынов Израилевых от Красного моря, и привел их в пустыню Сур; и шли они три дня в пустыне, и не находили воды, чтобы напиться. Пришли же в Мерру – и не могли пить воды из Мерры, ибо она была горька, поэтому наречено тому месту имя: «Горечь». И роптал народ на Моисея, говоря: «Что мы будем пить?» Моисей же воззвал ко Господу, и Господь показал ему дерево, и он бросил его в воду, и сделалась сладкой вода."},
  {"id": "ru-voz-0031", "section": "service", "who": "reader", "text": "Там установил ему (Бог) предписания и суды, и там испытывал его, и сказал: «Если будешь действительно слушаться (гласа) Господа, Бога твоего, и сотворишь угодное пред очами Его, и будешь внимать заповедям Его, и соблюдешь все повеления Его, то никакую болезнь, что Я навел на Египтян, не наведу на тебя, ибо Я – Господь, исцеляющий тебя."},
  {"id": "ru-voz-0032", "section": "service", "who": "reader", "text": "И пришли в Елим; и было там двенадцать источников воды и семьдесят стволов финиковых пальм, и расположились там станом при водах. И отправились из Елима, и пришло всё собрание сынов Израилевых в пустыню Син, что между Елимом и между Синаем. Исх 15:22–27; 16:1"},
  {"id": "ru-voz-0033", "section": "service", "who": "reader", "text": "2. Притчей чтение"},
  {"id": "ru-voz-0034", "section": "service", "who": "reader", "text": "Сын мой, не пренебрегай наказанием Господним, и не ослабевай, от Него обличаемый; ибо кого любит Господь, того наказывает, бичует же всякого сына, которого принимает. Блажен человек, который обрел премудрость, и смертный, который постиг разум, – ибо лучше её приобретать, чем сокровища из серебра и золота. Она дороже камней драгоценных: не воспротивится ей ничто дурное; она хорошо известна всем, любящим ее, и все драгоценное не достойно ее. Ибо долгота жития и годы жизни – в правой руке её, а в левой у неё – богатство и слава; из уст её выходит правда; закон же и милость она на языке носит; пути её – пути прекрасные, и все стези её – с миром. Она – древо жизни для всех, держащихся её, и для опирающихся на неё, как на Господа, – надежна. Притч 3:11–18"},
  {"id": "ru-voz-0035", "section": "service", "who": "reader", "text": "3. Пророчества Исаии чтение"},
  {"id": "ru-voz-0036", "section": "service", "who": "reader", "text": "Так говорит Господь: Отворены будут врата твои, Иерусалим, постоянно, днем и ночью, (и) не будут затворяться, чтобы ввести к тебе силу народов и царей их приводимых. Ибо народы и цари, которые не будут служить тебе, погибнут, и такие народы совершенно запустеют. И слава Ливана к тебе придет в кипарисе, и сосне, и кедре вместе, чтобы прославить место святое Мое; и место ног Моих Я прославлю. И придут к тебе в страхе сыновья смиривших тебя и раздраживших тебя, и преклонятся к следам ног твоих все, раздражившие тебя, и ты будешь назван городом Господа, Сионом Святого Израилева. За то, что ты был оставлен и ненавидим, и не было помощника тебе, Я и сделаю тебя радостью вечною, весельем родам родов. И будешь питаться молоком народов, и богатство царей вкусишь, и узнаешь, что Я – Господь, спасающий тебя, и избавляющий тебя – Бог Израилев. Ис 60:11–16"},
  {"id": "ru-voz-0037", "section": "service", "who": "reader", "text": "Стихиры на литии самогласные Андрея Иерусалимского, глас 1"},
  {"id": "ru-voz-0038", "section": "service", "who": "reader", "text": "В сей день святозвучное изречение Давида / воистину получило исполнение! / Ибо вот, мы явно поклоняемся / пречистых ног Твоих подножию / и, надеясь на осенение Твоими крыльями, Всемилосердный, взываем Тебе: / «Да отпечатлеется на нас свет лица Твоего, / и рог православных людей Твоих возвысь / воздвижением Креста Твоего, / Христе многомилостивый!»"},
  {"id": "ru-voz-0039", "section": "service", "who": "reader", "text": "Насажденное на Лобном месте / Древо подлинной жизни, / на котором совершил спасение / Царь веков посреди земли, / в сей день воздвигаемое, / освящает мира концы, / и храм Воскресения обновляется. / Радуются Ангелы на небе / и веселятся люди на земле, / как Давид взывая и возглашая: / «Возносите Господа Бога нашего / и поклоняйтесь подножию ног Его, / ибо свят Подающий миру великую милость!»"},
  {"id": "ru-voz-0040", "section": "service", "who": "reader", "text": "Прообразуя Крест Твой, Христе, / патриарх Иаков, когда внукам давал благословение, / руки на их головах переложил. / Мы же этот Крест в сей день воздвигая, восклицаем: / «Даруй христолюбивому царю победу, / как подал Константину врагов одоление!»"},
  {"id": "ru-voz-0041", "section": "service", "who": "reader", "text": "Феофана Начертанного, епископа Никейского, глас 2"},
  {"id": "ru-voz-0042", "section": "service", "who": "reader", "text": "Божественное сокровище, в земле скрывавшееся, – / Крест жизни Подателя – / на небесах явился благочестивому царю, / и о победе над врагами дает надпись, ясную для разума. / Тот же, радуясь, с верою и любовию / с Божьей помощью к возвышенному созерцанию поспешив, / с величайшим усердием из недр земных его выносит / для избавления мира и спасения душ наших."},
  {"id": "ru-voz-0043", "section": "service", "who": "rubric", "text": "Киприана Студита:"},
  {"id": "ru-voz-0044", "section": "service", "who": "reader", "text": "Переложение рук патриархом Иаковом / при благословении детей / предуказывало на могущественное Креста Твоего знамение. / И мы, владея им, несокрушимым хранителем, / всесильно отгоняем демонов полки; / и гордыню Велиара им низлагая, / в бегство обращаем враждебнейшего Амалика силу всегубительную. / Этот же Крест, ныне благоговейно воздвигаемый, / мы, верные, приносим Твоей благости в умилостивление за грехи, / взывая многократнейшим возгласом: «Господи, помилуй!» / Воплотившийся из Девы, сжалься, Благой, / над мудрым созданием рук Твоих!"},
  {"id": "ru-voz-0045", "section": "service", "who": "rubric", "text": "Льва VI Мудрого:"},
  {"id": "ru-voz-0046", "section": "service", "who": "reader", "text": "Ты мой мощный покров, / трехчастный Крест Христов, / освяти меня силою твоею, / чтобы я с верою и любовию / поклонялся и славил тебя!"},
  {"id": "ru-voz-0047", "section": "service", "who": "reader", "text": "Глас 4 Начнем рукоплескать сегодня песенному торжеству / и с радостным лицом и языком воскликнем ясно: / «Христе, ради нас осуждение принявший, / и оплевания, и раны, / и в багряницу облачившийся, и на Крест восшедший, / видя Которого солнце и луна сокрыли свет, / и земля от страха колебалась, / и разорвалась надвое завеса храма! / Ты и ныне сделай священный Свой Крест для нас хранителем, / стражем и гонителем демонов, / чтобы мы все, его целуя, восклицали ему: / «Спаси нас, Крест, силою своею! / Освяти нас светлостью своею, Священный Крест! / И укрепи нас своим воздвижением, / ибо ты дарован нам как свет / и спасение душ наших!» Анатолия:"},
  {"id": "ru-voz-0048", "section": "service", "who": "reader", "text": "Сверкающий звездами образ твой, Крест, / предвозвестил успех победный / славному благочестивому царю; / а мать его Елена тебя открыв, / соделала известным всему миру; / и сегодня, воздвигая тебя, / мы, хоры верных, восклицаем: / «Просвети нас светлостью своею, живоносный Крест! / Освяти нас крепостью твоею, всесвященный Крест! / Укрепи нас воздвижением твоим, / воздвигаемый против ополчения врагов!»"},
  {"id": "ru-voz-0049", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тот же, Анатолия"},
  {"id": "ru-voz-0050", "section": "service", "who": "reader", "text": "Моисей, предначертав действие священного Креста, Христе, / в бегство обратил враждебного Амалика в пустыне Синайской; / ибо когда распростирал он руки, образ Креста творя, / народ укреплялся; / ныне же исход этих событий на нас исполнился: / сегодня Крест воздвигается – и демоны бегут; / сегодня все творение от тления освободилось; / ибо благодаря Кресту нам засияли все благодатные дары; / потому все мы, радуясь, / припадаем к Тебе, возглашая: / «Как величественны дела Твои, Господи! Слава Тебе!»"},
  {"id": "ru-voz-0051", "section": "service", "who": "reader", "text": "Стихиры на стиховне самоподобные, глас 5"},
  {"id": "ru-voz-0052", "section": "service", "who": "reader", "text": "Радуйся, живоносный Крест, / знамение неодолимое благочестия победы, / дверь рая, верных утверждение, / Церкви ограждение, / которым уничтожено и упразднено проклятие, / и поглощена сила смерти, / и мы вознесены от земли к небесам; / оружие непобедимое, демонам противоборствующий, / слава мучеников, / преподобных истинное украшение, / пристанище спасения, / дарующий миру великую милость! Стих:"},
  {"id": "ru-voz-0053", "section": "service", "who": "reader", "text": "Возносите Господа, Бога нашего, и поклоняйтесь подножию ног Его, / ибо свято оно. Пс 98:5"},
  {"id": "ru-voz-0054", "section": "service", "who": "reader", "text": "Радуйся, Господень Крест, / которым от проклятия освободилось человечество, / подлинное знамение радости, / низвергающий врагов при твоем воздвижении, всеблагоговейно чтимый; / помощь наша, царей могущество, / сила праведных, священников благолепие; / изображаемый, и тем от бедствий избавляющий; / жезл силы, которым мы пасемся; / оружие мира, со страхом окружаемое Ангелами; / божественная слава Христа, / подающего миру великую милость. Стих:"},
  {"id": "ru-voz-0055", "section": "service", "who": "reader", "text": "Бог же, Царь наш прежде века, / соделал спасение посреди земли. Пс 73:12"},
  {"id": "ru-voz-0056", "section": "service", "who": "reader", "text": "Радуйся, слепых руководитель, недужных врач, / воскресение всех умерших, / возвысивший нас, в погибель впавших, / Крест драгоценный, / которым разрушено тление и расцвело нетление, / и мы, смертные, были обожены, / и диавол окончательно низвержен! / Видя тебя в сей день возвышаемым руками архиерейскими, / превозносим на тебе Вознесенного и поклоняемся тебе, / почерпая обильно великую милость."},
  {"id": "ru-voz-0057", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 8, преп. Иоанна Дамаскина"},
  {"id": "ru-voz-0058", "section": "service", "who": "reader", "text": "Тому, что в древности Моисей прообразовал собою / и Амалика, ниспровергнув, в бегство обратил, / и чему Давид певец, зовя его подножием Твоим, повелел кланяться, / драгоценному Кресту Твоему, Христе Боже, / мы грешные сегодня поклоняясь, / и устами недостойными воспевая Тебя, / соизволившего пригвоздиться на нем, Тебе взываем: / «Господи, удостой нас с разбойником Царствия Твоего!»"},
  {"id": "ru-voz-0059", "section": "service", "who": "reader", "text": "Тропарь, глас 1"},
  {"id": "ru-voz-0060", "section": "service", "who": "reader", "text": "Спаси, Господи, людей Твоих / и благослови наследие Твоё, / победы над неприятелями даруя / и Крестом Твоим сохраняя Твой народ. (3)"},
  {"id": "ru-voz-0061", "section": "service", "who": "rubric", "text": "Всемирное воздвижение священного и животворящего креста господня"},
  {"id": "ru-voz-0062", "section": "service", "who": "reader", "text": "НА УТРЕНИ На"},
  {"id": "ru-voz-0063", "section": "service", "who": "reader", "text": "Бог Господь:"},
  {"id": "ru-voz-0064", "section": "service", "who": "rubric", "text": "тропарь праздника, трижды:"},
  {"id": "ru-voz-0065", "section": "service", "who": "reader", "text": "Тропарь, глас 1 Спаси, Господи, людей Твоих / и благослови наследие Твоё, / победы над неприятелями даруя / и Крестом Твоим сохраняя Твой народ."},
  {"id": "ru-voz-0066", "section": "service", "who": "reader", "text": "По 1 стихословии седален, глас 6"},
  {"id": "ru-voz-0067", "section": "service", "who": "reader", "text": "Только лишь было водружено / древо Креста Твоего, Христе, / – и поколебались основания смерти, Господи: / ибо Того, Кого алчно поглотил ад, / он отпустил с трепетом. / Ты показал нам спасение Твое, Святой, / и мы славословим Тебя: / «Сын Божий, помилуй нас!»"},
  {"id": "ru-voz-0068", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 1 Подобен: Хотя камень был опечатан:"},
  {"id": "ru-voz-0069", "section": "service", "who": "reader", "text": "Древу Креста Твоего поклоняемся, Человеколюбец, / ибо на нем Ты пригвожден был, жизнь всех; / Ты рай отворил, Спаситель, / с верою приступившему к Тебе разбойнику, / и он наслаждения удостоился, исповедуя Тебя: / «Помяни меня, Господи!». / Прими, как его, и нас, восклицающих: / «Согрешили мы все, / по милосердию Твоему не презри нас!»"},
  {"id": "ru-voz-0070", "section": "service", "who": "reader", "text": "По 2 стихословии седален, глас 6"},
  {"id": "ru-voz-0071", "section": "service", "who": "reader", "text": "В сей день исполнилось пророческое слово: / ибо вот, мы поклоняемся месту, / где стояли ноги Твои, Господи; / и от Древа спасения вкусив, / свободу от страстей греховных получили / по молитвам Богородицы, единый Человеколюбец."},
  {"id": "ru-voz-0072", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 8 Подобен: Повеление таинственное:"},
  {"id": "ru-voz-0073", "section": "service", "who": "reader", "text": "В древние времена Иисус Навин / таинственно прообразовал Креста образ, / когда простер он руки крестовидно, / и остановилось солнце, / доколе он не истребил врагов, / сопротивлявшихся Тебе, Богу. / Ныне же оно померкло, / видя на Кресте, Тебя Спаситель мой, / разрушающего власть смерти / и ад разоряющего."},
  {"id": "ru-voz-0074", "section": "service", "who": "reader", "text": "Величание Величаем Тебя, / Податель жизни Христе, / и чтим Крест Твой святой, / которым Ты спас нас / от рабства врагу."},
  {"id": "ru-voz-0075", "section": "service", "who": "reader", "text": "Псалом избранный"},
  {"id": "ru-voz-0076", "section": "service", "who": "reader", "text": "Суди, Господи, обидчиков моих, сразись с воюющими со мной. / Возьмись за оружие и щит и восстань на помощь мне! / Отметил нас свет лица Твоего, Господи! / Как оружием благоволения Ты оградил нас. / Дал Ты боящимся Тебя знамение, чтобы убежать от лица лука. / Чтобы познали на земле путь Твой, во всех племенах – спасение Твоё. / Увидели все концы земли спасение Бога нашего. / Поклонимся месту, где стояли ноги Его. / Тогда возликуют все деревья дубравные. / Бог же, Царь наш прежде века, соделал спасение посреди земли. / Возносите Господа, Бога нашего, и поклоняйтесь подножию ног Его, ибо свято оно. / Благослови нас, Боже, Боже наш. Да благословит нас Бог. / Спаси народ Твой и благослови наследие Твоё. / И паси и вознеси их до века."},
  {"id": "ru-voz-0077", "section": "service", "who": "reader", "text": "Пс 34:1; 34:2; 4:7Б; 5:13Б; 59:6; 66:3; 97:3В; 131:7Б; 95:12Б; 73:12; 98:5; 66:7Б – 8А; 27:9А; 27:9Б"},
  {"id": "ru-voz-0078", "section": "service", "who": "reader", "text": "После полиелея седален, глас 8 Подобен: Повеление таинственное:"},
  {"id": "ru-voz-0079", "section": "service", "who": "reader", "text": "В раю меня некогда обнажило дерево, / вкушением от которого враг приносит умерщвление; / но древо Креста, одежду жизни людям приносящее, / водружено было на земле, / и весь мiр наполнился всякой радостью. / Видя его возносимым, люди, / Богу с верою согласно воззовем: / «Полон славы дом Твой!»"},
  {"id": "ru-voz-0080", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-voz-0081", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-voz-0082", "section": "service", "who": "rubric", "text": "Степенна, 1-й антифон 4-го гласа."},
  {"id": "ru-voz-0083", "section": "service", "who": "reader", "text": "Прокимен, глас 4 Увидели все концы земли / спасение Бога нашего. Стих:"},
  {"id": "ru-voz-0084", "section": "service", "who": "reader", "text": "Воспойте Господу песнь новую, ибо дивное сотворил Господь. Пс 97:3, 1А"},
  {"id": "ru-voz-0085", "section": "service", "who": "reader", "text": "Евангелие от Иоанна, зачало 42Б"},
  {"id": "ru-voz-0086", "section": "service", "who": "reader", "text": "Сказал Господь: «Отче, прославь имя Твое». Пришел же с неба глас: «И прославил, и снова прославлю!» Народ же, стоявший и слышавший, говорил: «Гром был». Другие говорили: «Ангел говорил Ему». Ответил Иисус и сказал: «Не для Меня был этот глас, но для вас. Ныне – суд миру сему; ныне князь мира сего изгнан будет вон. И Я, когда вознесен буду от земли, всех привлеку к Себе». А это Он говорил, давая понять, какою смертью предстояло Ему умереть. Ответил Ему народ: «Мы слышали из Закона, что Христос пребывает вовек; а как же Ты говоришь, что должно вознесену быть Сыну Человеческому? Кто этот Сын Человеческий?» Сказал же им Иисус: «Еще малое время свет с вами есть. Ходите, пока имеете свет, чтобы тьма вас не объяла; а ходящий во тьме не знает, куда идет. Пока имеете свет, веруйте в свет, чтобы стать вам сынами света!» Ин 12:28–36А Также поем:"},
  {"id": "ru-voz-0087", "section": "service", "who": "reader", "text": "Воскресение Христа увидев, / поклонимся Святому Господу Иисусу, / единому безгрешному. / Кресту Твоему поклоняемся, Христе, / и Святое воскресение Твоё поём и славим, / ибо Ты – Бог наш, / кроме Тебя иного не знаем, / имя Твоё призываем. / Придите, все верные, / поклонимся святому Христову воскресению, / ибо вот, пришла через Крест / радость всему мiру. / Всегда благословляя Господа, / воспеваем воскресение Его, / ибо Он, распятие претерпев, / смертию смерть сокрушил."},
  {"id": "ru-voz-0088", "section": "service", "who": "reader", "text": "После 50 псалма ["},
  {"id": "ru-voz-0089", "section": "service", "who": "reader", "text": "Слава, глас 2: Ты мой мощный покров, / трехчастный Крест Христов, / освяти меня силою твоею, / чтобы я с верою и любовию / поклонялся и славил тебя! И ныне:"},
  {"id": "ru-voz-0090", "section": "service", "who": "rubric", "text": "повторяем то же.]"},
  {"id": "ru-voz-0091", "section": "service", "who": "reader", "text": "Слава: По молитвам Апостолов, / Милостивый, изгладь / множество согрешений наших. И ныне: По молитвам Богородицы, / Милостивый, изгладь / множество согрешений наших."},
  {"id": "ru-voz-0092", "section": "service", "who": "reader", "text": "Помилуй меня, Боже, / по великой милости Твоей / и по множеству щедрот Твоих / изгладь беззаконие моё."},
  {"id": "ru-voz-0093", "section": "service", "who": "reader", "text": "Стихира, глас 6 Крест Христов, надежда христиан, / путеводитель заблуждающихся, / пристань носимых бурей, / победа в битвах, вселенной безопасность, / болящих врач, / мертвых воскресение, / помилуй нас."},
  {"id": "ru-voz-0094", "section": "service", "who": "reader", "text": "Канон"},
  {"id": "ru-voz-0095", "section": "service", "who": "rubric", "text": "Канон св. Космы Маиумского, глас 8; ирмосы канона исполняются дважды, тропари же поем на 12."},
  {"id": "ru-voz-0096", "section": "service", "who": "reader", "text": "Песнь 1 Ирмос:"},
  {"id": "ru-voz-0097", "section": "service", "who": "reader", "text": "Крест начертывая, Моисей / прямо рассек Красное море жезлом / для идущего пешком Израиля, / и то же море ударом поперек / обратно для Фараоновых колесниц соединил, / изобразив тем непобедимое оружие; / потому воспоем Христу Богу нашему: / ибо Он прославился."},
  {"id": "ru-voz-0098", "section": "service", "who": "reader", "text": "Образ пречистого страдания Моисей / в древности в себе самом явил, / стоя между освященных: / вид Креста приняв, он распростертыми руками / воздвиг знамение победы, / уничтожив силу Амалика всегубителя; / потому воспоем Христу Богу нашему, / ибо Он прославился."},
  {"id": "ru-voz-0099", "section": "service", "who": "reader", "text": "Возложил Моисей на столпе лекарство, / избавлявшее от губительного и ядовитого уязвления, / и поперек к дереву, образу Креста, / по земле пресмыкающегося змия привязал, / восторжествовав чрез то над бедствием; / потому воспоем Христу Богу нашему, / ибо Он прославился."},
  {"id": "ru-voz-0100", "section": "service", "who": "reader", "text": "Небо показало благочестивому властителю / и царю богомудрому / победное знамение Креста, / которым низвержена злобных врагов надменность, / обман же разрушен и вера божественная / распространилась по всем концам земли; / потому воспоем Христу Богу нашему, / ибо Он прославился."},
  {"id": "ru-voz-0101", "section": "service", "who": "reader", "text": "Песнь 3 Ирмос:"},
  {"id": "ru-voz-0102", "section": "service", "who": "reader", "text": "Жезл берется как образ таинства: / ибо произрастанием он указывает священника; / а для Церкви, прежде бесплодной, ныне расцвело / древо Креста к её силе и утверждению."},
  {"id": "ru-voz-0103", "section": "service", "who": "reader", "text": "Когда утес от удара воду источил / народу непокорному и жестокосердному, / он явил богозванной Церкви таинство, / для которой Крест – сила и утверждение."},
  {"id": "ru-voz-0104", "section": "service", "who": "reader", "text": "Когда пречистые ребра / пронзены были копьем, / то вода с кровью истекли, / обновляющие завет и очищающие от греха; / ибо Крест – верных хвала / и царей сила и утверждение."},
  {"id": "ru-voz-0105", "section": "service", "who": "reader", "text": "Седален, глас 4* Подобен: Скоро предстань:"},
  {"id": "ru-voz-0106", "section": "service", "who": "reader", "text": "Вчесть тебя, трижды блаженный / податель жизни, Крест, / люди пиршественно празднуют / вместе с невещественными хорами; / сонмы архиереев тебя благоговейно воспевают, / множество же монашествующих и постников поклоняется, / и Христа распятого все мы славим."},
  {"id": "ru-voz-0107", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-voz-0108", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-voz-0109", "section": "service", "who": "reader", "text": "Песнь 4 Ирмос:"},
  {"id": "ru-voz-0110", "section": "service", "who": "reader", "text": "Услышал я, Господи, / о таинстве Твоего промысла, / уразумел дела Твои, / и прославил Твое Божество."},
  {"id": "ru-voz-0111", "section": "service", "who": "reader", "text": "В древности Моисей деревом изменил / горькие по природе источники в пустыне, / предвещая обращение Крестом / язычников к благочестию."},
  {"id": "ru-voz-0112", "section": "service", "who": "reader", "text": "Иордан, сокрыв во глубине секиру, / с помощью дерева возвратил её, / знаменуя пресечение заблуждения / Крестом и крещением."},
  {"id": "ru-voz-0113", "section": "service", "who": "reader", "text": "Священно ополчается / четырехчастный народ, / шествующий перед прообразовательной скинией свидетельства, / славясь крестообразным построением."},
  {"id": "ru-voz-0114", "section": "service", "who": "reader", "text": "Чудесно распростертый Крест / испустил солнечные лучи, / и возвестили небеса / славу Бога нашего."},
  {"id": "ru-voz-0115", "section": "service", "who": "reader", "text": "Песнь 5 Ирмос:"},
  {"id": "ru-voz-0116", "section": "service", "who": "reader", "text": "О трижды блаженное Древо, / на котором был распят Христос, Царь и Господь, / чрез которое пал обольстивший древом, / сам уловленный Богом, / на тебе пригвожденном плотию, / дарующим мир душам нашим!"},
  {"id": "ru-voz-0117", "section": "service", "who": "reader", "text": "Тебя, прославленное древо, / Крест, на котором простерт был Христос, / устрашился вращающийся меч, Эдем охранявший, / а грозный Херувим отступил / перед пригвожденным на тебе Христом, / подающим мир душам нашим."},
  {"id": "ru-voz-0118", "section": "service", "who": "reader", "text": "Враждебные силы преисподней / трепещут знамения Креста, / начертываемого в воздухе, / в котором они витают; / а род небожителей и на земле рожденных / преклоняет колена пред Христом, / подающим мир душам нашим."},
  {"id": "ru-voz-0119", "section": "service", "who": "reader", "text": "Божественный Крест, / в чистых лучах явившись / и светом божественным озарив / народы, омраченные обманчивым заблуждением, / усвояет их пригвожденному на нем Христу, / подающему мир душам нашим."},
  {"id": "ru-voz-0120", "section": "service", "who": "reader", "text": "Песнь 6 Ирмос:"},
  {"id": "ru-voz-0121", "section": "service", "who": "reader", "text": "Во утробе морского зверя / Иона крестообразно руки распростер, / ясно прообразовав спасительное страдание; / выйдя же оттуда спустя три дня, / предначертал сверхъестественное воскресение / Христа Бога, пригвожденного плотию / и восстанием в третий день мир просветившего."},
  {"id": "ru-voz-0122", "section": "service", "who": "reader", "text": "Согнутый старостью и болезнью удрученный / Иаков выпрямился, когда руки на сынах Иосифа переложил, / действие являя животворящего Креста; / ибо пригвожденный на нем плотию Бог / ветхость тени подобного писанного Закона обновил / и отогнал душепагубную болезнь заблуждения."},
  {"id": "ru-voz-0123", "section": "service", "who": "reader", "text": "Крестообразно положив руки на юных головах, / давал понять Божественный Израиль, / что почитаемый старшим – это народ, служащий под законом; / потому он, заподозренный, что в том ошибся, / не изменил живоносного знамения: / «Ведь преимущество получит», – возглашал он, – / «народ новоутвержденный Христа Бога, / ограждаемый Крестом!»"},
  {"id": "ru-voz-0124", "section": "service", "who": "reader", "text": "Кондак самоподобный, глас 4"},
  {"id": "ru-voz-0125", "section": "service", "who": "reader", "text": "Вознесенный на Крест добровольно, / соименному Тебе новому народу / милости Твои даруй, Христе Боже; / возвесели силою Твоею верных людей Твоих*, / подавая им победы над врагами, / – да имеют они помощь от Тебя, / оружие мира, непобедимый знак победы. Икос:"},
  {"id": "ru-voz-0126", "section": "service", "who": "reader", "text": "До третьего неба вознесенный в рай / и услышавший неизреченные и божественные слова, / которые невозможно пересказывать языками человеческими, – / что он Галатам пишет, / как прочли и узнали вы, любители Писаний? / «Чтобы я, говорит он, хвалился, – да не будет, / разве только одним Крестом Господним, / на котором пострадав, Он убил страсти». / Так и мы все будем твердо держать его, / Крест Господень, как похвалу; / ибо для нас это спасительное Древо – / оружие мира, непобедимый знак победы. *греч.:"},
  {"id": "ru-voz-0127", "section": "service", "who": "reader", "text": "царей наших"},
  {"id": "ru-voz-0128", "section": "service", "who": "reader", "text": "Песнь 7 Ирмос:"},
  {"id": "ru-voz-0129", "section": "service", "who": "reader", "text": "Безумное веление тирана нечестивого, / дышащее угрозою и хулою богомерзкою, / в смятение народы привело; / однако трех отроков не устрашили / ни зверский гнев, ни огонь шумящий, / но, находясь в огне, / против которого веял росоносный ветер, они пели: / «Прехвальный Боже отцов и наш, благословен Ты!»"},
  {"id": "ru-voz-0130", "section": "service", "who": "reader", "text": "Первый из смертных, / вкусив от древа, впал в погибель, / ибо на бесславнейшее лишение жизни осужденный, / он, как некую губительную для тела порчу, / всему роду своему передал болезнь; / но мы, на земле рожденные, обретя восстановление / через древо Креста, взываем: / «Прехвальный Боже отцов и наш, благословен Ты!»"},
  {"id": "ru-voz-0131", "section": "service", "who": "reader", "text": "Ослушание нарушило Божие повеление / и дерево принесло людям смерть / чрез несвоевременное от него вкушение; / а потому древо драгоценной жизни / было для безопасности затворено; / но оно открылось злою смертию умершему разбойнику, / благоразумно взывавшему: / «Прехвальный отцов и наш Боже, благословен Ты!»"},
  {"id": "ru-voz-0132", "section": "service", "who": "reader", "text": "Созерцающий будущее Израиль / обнимает верх жезла Иосифа, / предвещая, что преславный Крест / возымеет царственную силу; / ибо он – победная хвала царей / и свет для взывающих с верою: / «Прехвальный отцов и наш Боже, благословен Ты!»"},
  {"id": "ru-voz-0133", "section": "service", "who": "reader", "text": "Песнь 8 Ирмос:"},
  {"id": "ru-voz-0134", "section": "service", "who": "reader", "text": "Благословляйте, отроки, / Троице равночисленные, / Бога Отца Создателя, / воспевайте Слово, сошедшее / и огонь в росу претворившее, / и превозносите всем жизнь подающего / Духа всесвятого, вовеки!"},
  {"id": "ru-voz-0135", "section": "service", "who": "reader", "text": "При воздвижении Древа, / окропленного кровью воплотившегося Слова Божия, / пойте, Небесные Силы, / восстановление смертных празднуя; / люди, поклоняйтесь Христову Кресту, / чрез который воскресение мира навеки."},
  {"id": "ru-voz-0136", "section": "service", "who": "reader", "text": "Земные управители благодати, / воздвигайте руками, как прилично святыне, / Крест, на котором стоял Христос Бог, / и копье, тело Бога Слова пронзившее; / да увидят все народы спасение Божие, / прославляя Его вовеки."},
  {"id": "ru-voz-0137", "section": "service", "who": "reader", "text": "Веселитесь, избранные волей Божественной / верные цари христианские: / получив от Бога священный Крест, / хвалитесь этим победоносным оружием: / ибо им племена, дерзко ищущие войн, / рассеиваются навеки. На 9-ой песни"},
  {"id": "ru-voz-0138", "section": "service", "who": "reader", "text": "Честью высшую Херувимов:"},
  {"id": "ru-voz-0139", "section": "service", "who": "rubric", "text": "не поем, даже в воскресенье, но поем припев праздника:"},
  {"id": "ru-voz-0140", "section": "service", "who": "reader", "text": "Величай, душа моя, / всесвященный Крест Господень. И ирмос:"},
  {"id": "ru-voz-0141", "section": "service", "who": "reader", "text": "Ты, Богородица, – таинственный рай:"},
  {"id": "ru-voz-0142", "section": "service", "who": "rubric", "text": "Затем второй хор поет тот же припев и ирмос. И к прочим шести стихам поем тот же припев."},
  {"id": "ru-voz-0143", "section": "service", "who": "reader", "text": "Песнь 9 Ирмос:"},
  {"id": "ru-voz-0144", "section": "service", "who": "reader", "text": "Ты, Богородица, – таинственный рай, / невозделанно произрастивший Христа, / Которым на земле насаждено / Креста живоносное древо; / потому ныне, при воздвижении его, / поклоняясь ему, мы Тебя величаем."},
  {"id": "ru-voz-0145", "section": "service", "who": "reader", "text": "Да возрадуются все деревья дубрав; / ибо освятилось естество их / Тем, Кто насадил их в начале – Христом, / распростертым на Древе; / потому ныне, при воздвижении его, / мы поклоняемся ему и величаем."},
  {"id": "ru-voz-0146", "section": "service", "who": "reader", "text": "Поднялся для богомудрых / рог священный Главы всего / – Крест, о который сокрушаются / все роги невещественных грешников; / потому ныне, при воздвижении его, / мы поклоняемся ему и величаем."},
  {"id": "ru-voz-0147", "section": "service", "who": "rubric", "text": "Другой припев праздника:"},
  {"id": "ru-voz-0148", "section": "service", "who": "reader", "text": "Величай, душа моя, / животворящего Креста Господня воздвижение. И ирмос:"},
  {"id": "ru-voz-0149", "section": "service", "who": "reader", "text": "Смерть, постигшая род наш:"},
  {"id": "ru-voz-0150", "section": "service", "who": "rubric", "text": "Затем второй хор поет тот же припев и ирмос. И к прочим шести стихам поем этот же припев."},
  {"id": "ru-voz-0151", "section": "service", "who": "reader", "text": "Иной Ирмос:"},
  {"id": "ru-voz-0152", "section": "service", "who": "reader", "text": "Смерть, постигшая род наш через вкушение от древа, / в сей день упразднена Крестом; / ибо всеобщее проклятие за вину праматери / разрушено Отраслью чистой Богоматери, / Которую все Силы Небесные величают."},
  {"id": "ru-voz-0153", "section": "service", "who": "reader", "text": "Не допустив убийственной горечи от древа, Господи, / Ты совершенно истребил её Крестом; / потому некогда дерево / горечь вод Мерры и прекратило, / предызображая действие Креста, / которое все силы небесные величают."},
  {"id": "ru-voz-0154", "section": "service", "who": "reader", "text": "Непрестанно погружавшихся во мраке праотца / Ты, Господи, возвысил в сей день Крестом: / ибо как прежде наше естество / крайне неудержимо низверглось заблуждением, / так вновь всецело исправил нас свет Креста Твоего, / который мы, верные, величаем."},
  {"id": "ru-voz-0155", "section": "service", "who": "reader", "text": "Чтобы миру показать поклоняемый образ Креста / во всей его славе, Господи, / Ты изобразил его на небе / в безмерном свете блистающим, / для царя непобедимым всеоружием, / которое все Силы Небесные величают."},
  {"id": "ru-voz-0156", "section": "service", "who": "reader", "text": "Светилен, глас 2 Подобен: Когда ученики на Тебя взирали:"},
  {"id": "ru-voz-0157", "section": "service", "who": "reader", "text": "Крест – хранитель всей вселенной, / Крест – красота Церкви, / Крест – царей могущество, / Крест – верных утверждение; / Крест – Ангелов слава / и демонов поражение. (2)"},
  {"id": "ru-voz-0158", "section": "service", "who": "reader", "text": "Слава, и ныне: Подобен: Жены, услышьте:"},
  {"id": "ru-voz-0159", "section": "service", "who": "reader", "text": "Крест сегодня воздвигается / и мир освящается; / ибо Ты, Христе, сидящий со Отцом и Духом Святым, / на нем простерши руки, / весь мир привлек к познанию Тебя. / Удостой же на Тебя надеющихся / божественной славы."},
  {"id": "ru-voz-0160", "section": "service", "who": "reader", "text": "На «Хвалите» стихиры на 4 самоподобные, глас 8"},
  {"id": "ru-voz-0161", "section": "service", "who": "reader", "text": "О дивное чудо! / Живоносное насаждение, Крест всесвятой, / является в сей день поднимаемым в высоту. / Славословят все концы земли, / устрашаются все демоны. / О, какой дар преподан смертным! / Им спаси, Христе, души наши, / как Единый милосердный! (2)"},
  {"id": "ru-voz-0162", "section": "service", "who": "reader", "text": "О дивное чудо! / Как полную жизни виноградную гроздь / Всевышнего на себе поднявший, / в сей день виден Крест, воздвигаемый от земли, / которым все мы к Богу привлечены / и до конца поглощена смерть. / О Древо непорочное, / благодаря которому мы наслаждаемся / той, что в Эдеме пищею бессмертия, / славя Христа!"},
  {"id": "ru-voz-0163", "section": "service", "who": "reader", "text": "О дивное чудо! / Ширина и длина Креста равны небесам, / ибо Божественною благодатию он освящает все. / Им варварские народы побеждаются, / им скипетры царей укрепляются. / О божественная лестница, / которою мы восходим на небеса, / превознося в песнях Христа Господа!"},
  {"id": "ru-voz-0164", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 6: В сей день совершает исхождение Крест Господень, / и верные принимают его с любовию, / и получают исцеление / души, и тела, и всякого недуга. / Его будем приветствовать с радостью и страхом: / со страхом – из-за греха, как недостойные; / с радостью же – ради спасения, которое миру подает / на нем пригвожденный Христос Господь, / имеющий великую милость."},
  {"id": "ru-voz-0165", "section": "service", "who": "rubric", "text": "И тихо и согласно поют великое славословие. В это время совершается каждение св. Престола, на котором возложен св. Крест. В конце славословия настоятель, сделав перед престолом три земных поклона, совершает вынос св. Креста северными вратами. Дойдя же до Царских врат, по окончании славословия он возглашает:"},
  {"id": "ru-voz-0166", "section": "service", "who": "choir", "text": "Премудрость! Станем благоговейно!"},
  {"id": "ru-voz-0167", "section": "service", "who": "rubric", "text": "И идет в центр храма к приготовленному столу, на который возлагается блюдо со св. Крестом, после чего совершается его троекратное каждение. Хор в это время поет тропарь"},
  {"id": "ru-voz-0168", "section": "service", "who": "choir", "text": "Спаси, Господи, людей Твоих: трижды."},
  {"id": "ru-voz-0169", "section": "service", "who": "rubric", "text": "[Далее, если совершается чин Воздвижения Креста, настоятель берет св. Крест с благовонными васильками (веточками базилика), и становится, обратившись лицом к востоку, диакон же возглашает:"},
  {"id": "ru-voz-0170", "section": "service", "who": "deacon", "text": "Помилуй нас, Боже, по великой милости Твоей, молимся Тебе, услышь нас, Господи, и помилуй; возгласим все:"},
  {"id": "ru-voz-0171", "section": "service", "who": "rubric", "text": "Хор начинает петь первую сотню"},
  {"id": "ru-voz-0172", "section": "service", "who": "deacon", "text": "Господи, помилуй."},
  {"id": "ru-voz-0173", "section": "service", "who": "rubric", "text": "Настоятель же в начале осеняет Крестом трижды, и затем, во время пения первой половины сотни склоняется с Крестом к земле, не достигая до нее только пяди, а во время второй половины сотни поднимается, воздвигая св. Крест, в конце же пения также осеняет Крестом трижды."},
  {"id": "ru-voz-0174", "section": "service", "who": "rubric", "text": "Таким же порядком совершается воздвижение еще четырежды, на четыре стороны света."},
  {"id": "ru-voz-0175", "section": "service", "who": "rubric", "text": "На запад:"},
  {"id": "ru-voz-0176", "section": "service", "who": "deacon", "text": "Ещё молимся о Святейшем Патриархе нашем (имя)"},
  {"id": "ru-voz-0177", "section": "service", "who": "deacon", "text": ", и о преосвященнейшем митрополите (или: архиепископе, или: епископе)"},
  {"id": "ru-voz-0178", "section": "service", "who": "deacon", "text": "нашем (имя)"},
  {"id": "ru-voz-0179", "section": "service", "who": "deacon", "text": ", и о всём во Христе братстве нашем, о здравии и спасении; возгласим все: На юг:"},
  {"id": "ru-voz-0180", "section": "service", "who": "deacon", "text": "Ещё молимся о богохранимой стране нашей Российской, о всём народе и властях её, да тихую и безмятежную жизнь проведём во всяком благочестии и чистоте; возгласим все: На север:"},
  {"id": "ru-voz-0181", "section": "service", "who": "deacon", "text": "Ещё молимся о всякой душе христианской, скорбящей и бедствующей, здравия, спасения и отпущения грехов требующей; возгласим все: На восток:"},
  {"id": "ru-voz-0182", "section": "service", "who": "deacon", "text": "Ещё молимся о всех служащих и послуживших во святой обители сей (или:"},
  {"id": "ru-voz-0183", "section": "service", "who": "deacon", "text": "в этом всесвященном храме )"},
  {"id": "ru-voz-0184", "section": "service", "who": "deacon", "text": "отцах и братьях наших, о здравии, и о спасении, и отпущении грехов их; возгласим все:"},
  {"id": "ru-voz-0185", "section": "service", "who": "rubric", "text": "После окочания пятой сотни"},
  {"id": "ru-voz-0186", "section": "service", "who": "deacon", "text": "Слава, и ныне:"},
  {"id": "ru-voz-0187", "section": "service", "who": "rubric", "text": "и поем кондак Кресту:"},
  {"id": "ru-voz-0188", "section": "service", "who": "deacon", "text": "Вознесенный на Крест добровольно: ]"},
  {"id": "ru-voz-0189", "section": "service", "who": "rubric", "text": "И затем поем на глас 6 тропарь с тремя земными поклонами:"},
  {"id": "ru-voz-0190", "section": "service", "who": "deacon", "text": "Кресту Твоему поклоняемся, Владыка, / и святое воскресение Твое славим."},
  {"id": "ru-voz-0191", "section": "service", "who": "rubric", "text": "Обычно тропарь трижды поют попеременно настоятель с клириками и хор."},
  {"id": "ru-voz-0192", "section": "service", "who": "rubric", "text": "Когда же целуем св. Крест поем:"},
  {"id": "ru-voz-0193", "section": "service", "who": "deacon", "text": "Стихиры самогласные св. Креста, глас 2"},
  {"id": "ru-voz-0194", "section": "service", "who": "deacon", "text": "Придите, верные, / животворящему Древу поклонимся, / на котором Христос, Царь славы, / добровольно руки распростер / и возвысил к прежнему блаженству / нас, которых враг, услаждением ограбив, / соделал изгнанными от Бога. / Придите, верные, поклонимся Древу, / благодаря которому мы удостоились / сокрушать головы невидимых врагов. / Придите, все племена народов, / Крест Господень песнопениями почтим. / Радуйся Крест, падшего Адама совершенное искупление! / Тобою вернейшие цари наши хвалятся, / ибо они твоею силою / народ измаильтян могущественно покоряют. / Ныне тебя со страхом целуя, / мы, христиане, славим / пригвожденного на тебе Бога, возглашая: / «Распятый на нем, Господи, помилуй нас, / как благой и Человеколюбец!» Глас 5:"},
  {"id": "ru-voz-0195", "section": "service", "who": "deacon", "text": "Придите люди, / необычайное чудо созерцая, / преклонимся пред силою Креста; / ибо дерево в раю произрастило смерть, / а это жизнью расцвело, / имея Господа безгрешного пригвожденным на себе. / Собирая с него плоды нетления, / мы, все народы, восклицаем: / «Крестом упразднивший смерть / и нас освободивший, слава Тебе!» Глас тот же:"},
  {"id": "ru-voz-0196", "section": "service", "who": "deacon", "text": "Исполнился глас пророков Твоих, Боже, / Исаии и Давида, возвещающий: / «Придут все народы, Господи, / и поклонятся пред Тобою». / Ибо вот, народ, благодати Твоей исполненный, / в Твоих, Благой, дворах Иерусалимских. / Крест претерпевший за нас / и Оживотворяющий нас воскресением Твоим, / сохрани и спаси нас! Глас 6:"},
  {"id": "ru-voz-0197", "section": "service", "who": "deacon", "text": "Четырехконечный мир в сей день освящается / при воздвижении четырехчастного Креста Твоего, Христе Боже наш, / и вместе с тем возвышается рог верных царей наших, / им сокрушающих роги врагов. / Велик Ты, Господи, / и дивен в делах Своих. Слава Тебе!"},
  {"id": "ru-voz-0198", "section": "service", "who": "deacon", "text": "Голоса пророков предвозвестили святое Древо, / которым Адам освободился / от древнего проклятия на смерть; / творение же в сей день при его воздвижении / также возвышает глас, / прося у Бога богатой милости. / Но, единственный неизмеримый в милосердии Владыка, / стань умилостивлением за нас / и спаси души наши! Глас 8:"},
  {"id": "ru-voz-0199", "section": "service", "who": "deacon", "text": "Исполнился глас пророка Твоего, Боже, Моисея, возвещающий: / «Увидите Жизнь вашу, висящую пред очами вашими». / В сей день Крест воздвигается – / и мир освобожден от заблуждения; / в сей день Христово Воскресение обновляется / и концы земли радуются, / принося Тебе песнопение на кимвалах, по Давиду, и возглашая: / «Ты соделал спасение среди земли, Боже – / Крест и Воскресение, / которыми спас нас, Благой и Человеколюбец. / Всесильный Господи, слава Тебе!» Глас тот же:"},
  {"id": "ru-voz-0200", "section": "service", "who": "deacon", "text": "В сей день Владыка творения и Господь славы / ко Кресту пригвождается / и в ребра пронзается; / желчи и уксуса вкушает Услада Церкви; / венец из терний возлагается / на Покрывающего небо облаками; / в одежду посмеяния облекают / и бьют по лицу созданной из земли рукою / Создавшего Своей рукою человека; / по спине бичуют / Одевающего небо облаками; / принимает оплевания и раны, / оскорбления и удары / и все терпит ради меня, осужденного, / Искупитель мой и Бог, / да спасет мир от заблуждения, как Милосердный."},
  {"id": "ru-voz-0201", "section": "service", "who": "deacon", "text": "Слава, и ныне, глас тот же: В сей день Неприступный по существу / доступным мне становится / и терпит страдания / Освобождающий меня от страстей; / подающий свет слепым / оплевывается беззаконными устами / и за пленников подставляет спину ранам. / Его видя на Кресте, / чистая Дева и Матерь мучительно вещала: / «Увы Мне, Дитя Мое, что Ты это сделал? / Цветущий красотою более всех людей, / бездыханным, невзрачным являешься, / не имеющим ни вида, ни красоты. / Увы Мне, Свет Мой, / не могу спящим видеть Тебя, / терзаюсь внутренно и страшный меч сквозь сердце Мое проходит. / Воспеваю страдания Твои, / поклоняюсь милосердию Твоему; / долготерпеливый Господи, слава Тебе!»"},
  {"id": "ru-voz-0202", "section": "service", "who": "deacon", "text": "Отпуст Христос, истинный Бог наш, по молитвам пречистой Своей Матери, силою священного и животворящего Креста, святых славных и всехвальных Апостолов, святых и праведных Богоотцов Иоакима и Анны и всех святых помилует и спасет нас, как благой и Человеколюбец."},
  {"id": "ru-voz-0203", "section": "service", "who": "rubric", "text": "Всемирное воздвижение священного и животворящего креста господня"},
  {"id": "ru-voz-0204", "section": "service", "who": "deacon", "text": "НА ЛИТУРГИИ"},
  {"id": "ru-voz-0205", "section": "service", "who": "deacon", "text": "Антифон 1, глас 2 Стих 1:"},
  {"id": "ru-voz-0206", "section": "service", "who": "deacon", "text": "Боже, Боже мой, внемли мне, / для чего Ты оставил меня? Пс 21:2А"},
  {"id": "ru-voz-0207", "section": "service", "who": "deacon", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Стих 2:"},
  {"id": "ru-voz-0208", "section": "service", "who": "deacon", "text": "Удалила меня от спасения / вина грехопадений моих. Пс 21:2Б"},
  {"id": "ru-voz-0209", "section": "service", "who": "deacon", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Стих 3:"},
  {"id": "ru-voz-0210", "section": "service", "who": "deacon", "text": "Боже мой, я буду взывать днём – и Ты не услышишь; / и ночью – и это не в неразумие мне. Пс 21:3"},
  {"id": "ru-voz-0211", "section": "service", "who": "deacon", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Стих 4:"},
  {"id": "ru-voz-0212", "section": "service", "who": "deacon", "text": "Но Ты живёшь во святилище, / Похвала Израиля! Пс 21:4"},
  {"id": "ru-voz-0213", "section": "service", "who": "deacon", "text": "По молитвам Богородицы, Спаситель, / спаси нас."},
  {"id": "ru-voz-0214", "section": "service", "who": "deacon", "text": "Слава, и ныне: По молитвам Богородицы, Спаситель, / спаси нас."},
  {"id": "ru-voz-0215", "section": "service", "who": "deacon", "text": "Антифон 2, глас 2 Стих 1:"},
  {"id": "ru-voz-0216", "section": "service", "who": "deacon", "text": "Для чего Ты, Боже, / отверг до конца? Пс 73:1А"},
  {"id": "ru-voz-0217", "section": "service", "who": "deacon", "text": "Спаси нас, Сын Божий, / плотию распятый, поющих Тебе: аллилуиа. Стих 2:"},
  {"id": "ru-voz-0218", "section": "service", "who": "deacon", "text": "Вспомни сонм Твой, / который Ты приобрёл от начала. Пс 73:2А"},
  {"id": "ru-voz-0219", "section": "service", "who": "deacon", "text": "Спаси нас, Сын Божий, / плотию распятый, поющих Тебе: аллилуиа. Стих 3:"},
  {"id": "ru-voz-0220", "section": "service", "who": "deacon", "text": "Эту гору Сион, / на которой Ты поселился. Пс 73:2В"},
  {"id": "ru-voz-0221", "section": "service", "who": "deacon", "text": "Спаси нас, Сын Божий, / плотию распятый, поющих Тебе: аллилуиа. Стих 4:"},
  {"id": "ru-voz-0222", "section": "service", "who": "deacon", "text": "Бог же, Царь наш прежде века, / соделал спасение посреди земли. Пс 73:12"},
  {"id": "ru-voz-0223", "section": "service", "who": "deacon", "text": "Спаси нас, Сын Божий, / плотию распятый, поющих Тебе: аллилуиа."},
  {"id": "ru-voz-0224", "section": "service", "who": "deacon", "text": "Слава, и ныне: Единородный Сын:"},
  {"id": "ru-voz-0225", "section": "service", "who": "deacon", "text": "Антифон 3, глас 1 Стих 1:"},
  {"id": "ru-voz-0226", "section": "service", "who": "deacon", "text": "Господь воцарился: / пусть гневаются народы! Пс 98:1А"},
  {"id": "ru-voz-0227", "section": "service", "who": "deacon", "text": "Тропарь, глас 1 Спаси, Господи, людей Твоих / и благослови наследие Твоё, / победы над неприятелями даруя / и Крестом Твоим сохраняя Твой народ. Стих 2:"},
  {"id": "ru-voz-0228", "section": "service", "who": "deacon", "text": "Господь воцарился: пусть гневаются народы! / Восседающий на Херувимах: да потрясётся земля! Пс 98:1 Тропарь:"},
  {"id": "ru-voz-0229", "section": "service", "who": "deacon", "text": "Спаси, Господи, людей Твоих: Стих 3:"},
  {"id": "ru-voz-0230", "section": "service", "who": "deacon", "text": "Господь на Сионе велик / и высок над всеми народами. Пс 98:2 Тропарь:"},
  {"id": "ru-voz-0231", "section": "service", "who": "deacon", "text": "Спаси, Господи, людей Твоих: Стих 4:"},
  {"id": "ru-voz-0232", "section": "service", "who": "deacon", "text": "Поклонитесь Господу / во дворе святом Его. Пс 95:9А Тропарь:"},
  {"id": "ru-voz-0233", "section": "service", "who": "deacon", "text": "Спаси, Господи, людей Твоих:"},
  {"id": "ru-voz-0234", "section": "service", "who": "deacon", "text": "Входный стих Возносите Господа, Бога нашего, и поклоняйтесь подножию ног Его, ибо свято оно. Пс 98:5 Тропарь:"},
  {"id": "ru-voz-0235", "section": "service", "who": "deacon", "text": "Спаси, Господи, людей Твоих: Слава, и ныне:"},
  {"id": "ru-voz-0236", "section": "service", "who": "deacon", "text": "Кондак, глас 4 Вознесенный на Крест добровольно, / соименному Тебе новому народу / милости Твои даруй, Христе Боже; / возвесели силою Твоею верных людей Твоих, / подавая им победы над врагами, / – да имеют они помощь от Тебя, / оружие мира, непобедимый знак победы."},
  {"id": "ru-voz-0237", "section": "service", "who": "deacon", "text": "Вместо Трисвятого: Кресту Твоему поклоняемся, Владыка, / и святое воскресение Твое славим. (3)"},
  {"id": "ru-voz-0238", "section": "service", "who": "deacon", "text": "Прокимен, глас 7 Возносите Господа, Бога нашего, и поклоняйтесь подножию ног Его, / ибо свято оно. Стих:"},
  {"id": "ru-voz-0239", "section": "service", "who": "deacon", "text": "Господь воцарился: пусть гневаются народы! Пс 98:5, 1А"},
  {"id": "ru-voz-0240", "section": "service", "who": "deacon", "text": "Первое послание к Коринфянам, зачало 125А"},
  {"id": "ru-voz-0241", "section": "service", "who": "deacon", "text": "Братья, слово о Кресте для погибающих есть безумие, а для нас, спасаемых, – сила Божия. Ибо написано: «Погублю мудрость мудрецов, и разум разумных отвергну». Где мудрец? Где книжник? Где совопросник века сего? Не обратил ли Бог мудрость мира сего в безумие? Ведь поскольку мир своею мудростью не познал Бога в премудрости Божией, – благоволил Бог безумием проповеди спасти верующих. Ибо и Иудеи требуют знамений, и Эллины ищут мудрости, мы же проповедуем Христа распятого: для Иудеев – соблазн, а для Эллинов – безумие; для самих же призванных, как Иудеев, так и Эллинов, Христа – Божию силу и Божию премудрость. 1 Кор 1:18–24"},
  {"id": "ru-voz-0242", "section": "service", "who": "deacon", "text": "Аллилуиа, глас 1 Стих:"},
  {"id": "ru-voz-0243", "section": "service", "who": "deacon", "text": "Вспомни сонм Твой, который приобрёл Ты от начала. Стих:"},
  {"id": "ru-voz-0244", "section": "service", "who": "deacon", "text": "Бог же, Царь наш прежде века, соделал спасение посреди земли. Пс 73:2А, 12"},
  {"id": "ru-voz-0245", "section": "service", "who": "deacon", "text": "Евангелие от Иоанна, зачало 60"},
  {"id": "ru-voz-0246", "section": "service", "who": "deacon", "text": "В то время первосвященники и старейшины собрали совет против Иисуса, чтобы погубить его. И пришли к Пилату, возглашая: «Распни, распни Его!» Говорит им Пилат: «Возьмите Его вы и распните, ибо я не нахожу в Нем вины». Ответили ему Иудеи: «Мы имеем Закон, и по Закону нашему Он должен умереть, потому что сделал Себя Сыном Божиим»."},
  {"id": "ru-voz-0247", "section": "service", "who": "deacon", "text": "Когда же услышал Пилат это слово, он еще сильнее убоялся, и вошел в преторию снова и говорит Иисусу: «Откуда Ты?» Но Иисус ответа не дал ему. Говорит же Ему Пилат: «Со мной ли не говоришь? Не знаешь ли, что я власть имею распять Тебя, и власть имею отпустить Тебя?» Ответил Иисус: «Ты не имел бы надо Мной никакой власти, если бы не было дано тебе свыше»."},
  {"id": "ru-voz-0248", "section": "service", "who": "deacon", "text": "Итак, Пилат, услышав это слово, вывел вон Иисуса и сел на судейском престоле на месте, называемом «Каменный помост», а по-еврейски Гаввафа. Была же пятница перед Пасхой, и около шестого часа. И говорит он Иудеям: «Вот, Царь ваш». Они же закричали: «Возьми, возьми, распни Его!» Говорит им Пилат: «Царя ли вашего распну?» Ответили первосвященники: «Нет у нас царя, кроме кесаря». Тогда-то он и предал Его им на распятие. И взяли Иисуса и повели. И неся Крест Свой, Он вышел на место, называемое Лобным, которое зовется по-еврейски Голгофа, где Его распяли, и с Ним двух других, по ту и по другую сторону Его; посредине же – Иисуса. Написал же и надпись Пилат и поставил на кресте. Было же написано: «Иисус Назорей, Царь Иудейский». Так вот, эту надпись многие прочли из Иудеев, потому что близко было от города то место, где был распят Иисус, и было написано по-еврейски, по-гречески, по-римски."},
  {"id": "ru-voz-0249", "section": "service", "who": "deacon", "text": "Стояли же при Кресте Иисуса Матерь Его, и сестра Матери Его, Мария Клеопова, и Мария Магдалина. Иисус же, увидев Матерь и ученика, близ стоящего, которого Он любил, говорит Матери Своей: «Женщина, вот сын Твой». Потом говорит ученику: «Вот, Матерь твоя». И с того часа взял ученик тот Ее к себе. После этого Иисус, зная, что все уже совершилось, склонив голову, предал дух."},
  {"id": "ru-voz-0250", "section": "service", "who": "deacon", "text": "А как была пятница, то Иудеи, чтобы тела не остались на кресте в субботу – ибо был день той субботы днем великим, – попросили Пилата, чтобы перебить у них голени и снять их. Итак, пришли воины, и у первого перебили голени, и у другого, распятого с Ним. Придя же к Иисусу, они, когда увидели Его уже умершим, не перебили у Него голеней, но один из воинов копьем пронзил Ему ребра, и тотчас вышла кровь и вода. И видевший засвидетельствовал, и истинно свидетельство его. Мф 27:1–2; Ин 19:6Б-11А, 13–20, 25–28А, 30Б-35А"},
  {"id": "ru-voz-0251", "section": "service", "who": "deacon", "text": "Вместо «Достойно»"},
  {"id": "ru-voz-0252", "section": "service", "who": "deacon", "text": "Величай, душа моя, / всесвященный Крест Господень."},
  {"id": "ru-voz-0253", "section": "service", "who": "rubric", "text": "Ирмос, глас 8:"},
  {"id": "ru-voz-0254", "section": "service", "who": "deacon", "text": "Ты, Богородица, – таинственный рай, / невозделанно произрастивший Христа, / Которым на земле насаждено / Креста живоносное древо; / потому ныне, при воздвижении его, / поклоняясь ему, мы Тебя величаем. И до отдания."},
];

